class Solution {
    public: int longestMountain(vector<int>& arr){
        int answer=0,up=0,down=0;
        for(int i=1;i<(int)arr.size();++i){
            if(arr[i]==arr[i-1]||(down>0&&arr[i]>arr[i-1]))up=down=0;
            if(arr[i]>arr[i-1])++up;
            else if(arr[i]<arr[i-1])++down;
            if(up&&down)answer=max(answer,up+down+1);
        }
        return answer;
    }
};
